export const aliases={...routeChanges,...Object.fromEntries(Object.entries(overrides).map(([id,row])=>[id,row[0]]))};
export function makePages(inventory){
 const selected=inventory.pages.filter(p=>!mergedPages.includes(p.id));
 const urlMap={...routeChanges};for(const p of selected)if(overrides[p.id])urlMap[p.url]=overrides[p.id][0];
 const pages=publicCopy(selected).map(p=>{const row=overrides[p.id];if(row)p={...p,url:row[0],h1:row[1],family:row[2]||p.family};p.links=p.links.split(' ; ').map(u=>urlMap[u]||u).join(' ; ');return p;});
 for(const [id,family,url,h1,refs] of extras)pages.push({id,family,url,h1,title:h1+' | 100 Pilot',priority:'P2',refs,links:'/services/ ; /solutions/ ; /contact/',ds:'',angle:''});
 for(const p of pages){const profile=profiles[p.id];if(profile&&p.family==='Solution')p.h1=profile.title;if(cases[p.id]?.title)p.h1=cases[p.id].title;p.title=p.h1+' | 100 Pilot';}
 return pages;
}
